<?php
require __DIR__.'/app/bootstrap.php';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$action=$_POST['action']??'';try{if($action==='add'){cart_add((int)($_POST['product_id']??0),(int)($_POST['quantity']??1));flash('success','Ürün sepetinize eklendi.');}elseif($action==='update'){cart_update($_POST['qty']??[]);flash('success','Sepetiniz güncellendi.');}}catch(Throwable $e){flash('error',$e->getMessage());}redirect_to('cart.php');}
$items=cart_items();$subtotal=cart_subtotal();page_view('cart');$pageTitle='Sepetim | TOPLUCA';require __DIR__.'/includes/header.php';?>
<section class="page-hero"><div class="container"><div class="breadcrumbs"><a href="<?=app_url()?>">Ana Sayfa</a><span>›</span><span>Sepetim</span></div><h1>Sepetim</h1><p><?=cart_count()?> ürün</p></div></section><section class="cart-page"><div class="container cart-grid"><div><?php if(!$items):?><div class="empty"><h3>Sepetiniz boş.</h3><p>İhtiyacınız olan ürünleri keşfetmeye başlayın.</p><a class="primary-btn" href="<?=app_url()?>">Alışverişe Başla</a></div><?php else:?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="update"><div class="cart-list"><?php foreach($items as $it):?><div class="cart-row"><div class="cart-image"><?php if($it['primary_image']):?><img src="<?=app_url($it['primary_image'])?>" alt="<?=h($it['name'])?>"><?php else:?><span><?=h(mb_substr($it['name'],0,1))?></span><?php endif;?></div><div><a class="cart-name" href="<?=app_url('product.php?slug='.urlencode($it['slug']))?>"><?=h($it['name'])?></a><div class="cart-brand"><?=h($it['brand_name'])?> · <?=h($it['sku'])?></div></div><div class="cart-price"><?=money($it['unit_price'])?></div><input style="width:72px;padding:8px;border:1px solid #ddd;border-radius:7px" type="number" min="0" max="99" name="qty[<?=(int)$it['cart_item_id']?>]" value="<?=(int)$it['quantity']?>"><strong><?=money($it['line_total'])?></strong></div><?php endforeach;?></div><button class="secondary-btn" style="margin-top:12px" type="submit">Sepeti Güncelle</button></form><?php endif;?></div><?php if($items):?><aside class="cart-summary"><h3>Sipariş Özeti</h3><div class="summary-row"><span>Ürünler</span><b><?=money($subtotal)?></b></div><div class="summary-row"><span>Teslimat</span><b>Adres sonrası</b></div><div class="summary-row total"><span>Ara toplam</span><span><?=money($subtotal)?></span></div><?php $free=(float)setting('free_shipping_limit',750);if($subtotal<$free):?><div class="summary-note">🚚 <?=money($free-$subtotal)?> daha ekleyin, standart ücretsiz kargo limitine ulaşın.</div><?php endif;?><a class="summary-button" href="<?=app_url('checkout.php?step=address')?>">Teslimat Bilgilerine Geç →</a><p class="admin-note">Kargo seçimi adresinizi girdikten sonra yapılır. Ankara aynı gün uygunluğu da bu aşamada hesaplanır.</p></aside><?php endif;?></div></section><?php require __DIR__.'/includes/footer.php';?>